<script setup>
import {computed,ref} from 'vue';import {useTimeline} from './useTimeline';import {clock,INCIDENT} from './data';
const {filtered,select}=useTimeline();const mode=ref('incident');
const ids=computed(()=>mode.value==='incident'?['EV-106','EV-107','EV-109','EV-110','EV-111']:['EV-103','EV-101','EV-105']);
const chain=computed(()=>ids.value.map(id=>filtered.value.find(e=>e.id===id)).filter(Boolean).sort((a,b)=>a.t-b.t));
const columns=[{id:'messages',label:'מערכת IFF'},{id:'services',label:'שרת השירותים'},{id:'operator',label:'עמדת המפעיל'},{id:'voice',label:'מערכת הקשר'}];
</script><template><div class="path-toolbar"><label>קבוצת הצלבה <select v-model="mode"><option value="incident">T-041 / MSG-740 · האירוע</option><option value="background">רשומות רקע · ללא קישור מוכח</option></select></label><span>מיקוד לפי מזהה, ללא תלות בטווח הכללי · מרווח שווה בין רשומות</span></div><div class="message-path"><div class="path-heading"><b>זמן ↓</b><strong v-for="s in columns" :key="s.id">{{s.label}}</strong></div><div v-for="e in chain" :key="e.id" class="path-row"><time>{{clock(e.t)}}<small v-if="mode==='incident'">{{e.t-INCIDENT}}+ שנ׳</small></time><div v-for="s in columns" :key="s.id" class="path-cell"><button v-if="s.id===e.source" :class="{alert:e.severity!=='normal'}" @click="select(e.id)">{{e.title}}<small>{{e.id}}{{e.end?' · אינטרוול':''}}</small></button><div v-if="e.id==='EV-106'&&s.id==='services'" class="transfer">→ נשלח לעיבוד<br><small>MSG-740 · לפי EV-106</small></div><div v-if="e.id==='EV-107'&&s.id==='operator'" class="missing-delivery">⊘ אין אישור מסירה<br><small>פער בראיות, לא העברה מוכחת</small></div></div></div><p v-if="!chain.length" class="empty">אין רשומות בקבוצה תחת המסננים הנוכחיים.</p></div><p class="plot-note">ל־EV-106 ול־EV-107 יש מזהה MSG-740 משותף. יתר הרשומות מוצלבות לפי T-041 בלבד; סדר זמנים אינו הוכחת סיבתיות.</p></template>